// Valida la petición del agente y prepara el rango del día.
const TZ = 'America/Guayaquil';
const LEAD_MIN = 15;      // anticipación mínima para citas de hoy
const MAX_DIAS = 60;      // hasta cuántos días adelante se agenda
const SLOT_MIN = 30;      // cada cuántos minutos empieza un turno
const input = $('Entrada').first().json;
const info = $('Info negocio').first().json;
const fail = (error, mensaje) => [{ json: { valido: false, ok: false, error, mensaje } }];

const accion = String(input.accion || '').trim().toLowerCase();
if (!['turnos', 'agendar'].includes(accion)) return fail('ACCION_INVALIDA', 'accion debe ser turnos o agendar');

const fechaTxt = String(input.fecha || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(fechaTxt)) return fail('FECHA_INVALIDA', 'La fecha debe tener formato YYYY-MM-DD');
const dia = DateTime.fromISO(fechaTxt, { zone: TZ });
if (!dia.isValid) return fail('FECHA_INVALIDA', 'La fecha no existe');
const hoy = DateTime.now().setZone(TZ).startOf('day');
if (dia < hoy) return fail('FECHA_PASADA', 'La fecha ya pasó');
if (dia > hoy.plus({ days: MAX_DIAS })) return fail('FECHA_MUY_LEJANA', 'Solo se agenda hasta ' + MAX_DIAS + ' días adelante');

const servicios = info.servicios || [];
const q = String(input.servicio || '').trim().toLowerCase();
const servicio = servicios.find(s => s.service_id === q) || servicios.find(s => s.nombre.toLowerCase() === q)
  || servicios.find(s => q && (s.nombre.toLowerCase().includes(q) || q.includes(s.nombre.toLowerCase())));
if (!servicio) return fail('SERVICIO_INVALIDO', 'Servicios disponibles: ' + servicios.map(s => s.nombre).join(', '));

const nombresDia = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const nombreDia = nombresDia[dia.weekday % 7];
const horario = (info.horario || []).find(h => h.dia === nombreDia);
if (!horario || !horario.abierto) return fail('DIA_CERRADO', 'El ' + nombreDia + ' estamos cerrados');

const [ah, am] = horario.abre.split(':').map(Number);
const [ch, cm] = horario.cierra.split(':').map(Number);
const apertura = dia.set({ hour: ah, minute: am });
const cierre = dia.set({ hour: ch, minute: cm });

let horaPedida = null;
if (accion === 'agendar') {
  const h = String(input.hora || '').trim();
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(h)) return fail('HORA_INVALIDA', 'La hora debe tener formato HH:MM (24h)');
  const nombre = String(input.nombre || '').trim();
  if (nombre.length < 2 || nombre.length > 80) return fail('NOMBRE_INVALIDO', 'Falta el nombre del cliente');
  horaPedida = h;
}

return [{ json: {
  valido: true, accion, fecha: fechaTxt, dia_semana: nombreDia,
  servicio: servicio.nombre, precio: servicio.precio, duracion_min: Number(servicio.duracion_min),
  apertura: apertura.toISO(), cierre: cierre.toISO(), slot_min: SLOT_MIN, lead_min: LEAD_MIN,
  hora: horaPedida, nombre: String(input.nombre || '').trim(), telefono: String(input.telefono || '').trim(),
  negocio: info.negocio?.nombre || '', direccion: info.negocio?.direccion || ''
} }];

// Calcula turnos libres cruzando el horario con los eventos ocupados de Google Calendar.
const TZ = 'America/Guayaquil';
const req = $('Validar entrada').first().json;
const apertura = DateTime.fromISO(req.apertura, { zone: TZ });
const cierre = DateTime.fromISO(req.cierre, { zone: TZ });
const minimo = DateTime.now().setZone(TZ).plus({ minutes: req.lead_min });

const ocupados = [];
for (const it of $input.all()) {
  const ev = it.json || {};
  if (!ev.start || ev.status === 'cancelled' || ev.transparency === 'transparent') continue;
  const ini = ev.start.dateTime ? DateTime.fromISO(ev.start.dateTime) : DateTime.fromISO(ev.start.date, { zone: TZ });
  const fin = ev.end?.dateTime ? DateTime.fromISO(ev.end.dateTime) : DateTime.fromISO(ev.end?.date || ev.start.date, { zone: TZ }).plus(ev.end?.date ? {} : { days: 1 });
  if (ini.isValid && fin.isValid) ocupados.push([ini, fin]);
}

const libres = [];
for (let t = apertura; t.plus({ minutes: req.duracion_min }) <= cierre; t = t.plus({ minutes: req.slot_min })) {
  const f = t.plus({ minutes: req.duracion_min });
  if (t < minimo) continue;
  if (ocupados.some(([a, b]) => t < b && f > a)) continue;
  libres.push(t.toFormat('HH:mm'));
}

const base = { fecha: req.fecha, dia_semana: req.dia_semana, servicio: req.servicio, precio: req.precio, duracion_min: req.duracion_min };

if (req.accion === 'turnos') {
  return [{ json: { ok: true, crear: false, ...base, turnos_libres: libres,
    mensaje: libres.length ? 'Turnos libres encontrados' : 'No hay turnos libres ese día' } }];
}

if (!libres.includes(req.hora)) {
  return [{ json: { ok: false, crear: false, error: 'HORA_NO_DISPONIBLE', ...base, hora: req.hora,
    turnos_libres: libres, mensaje: 'Esa hora no está disponible. Ofrece otra de turnos_libres.' } }];
}

const [hh, mm] = req.hora.split(':').map(Number);
const inicio = DateTime.fromISO(req.fecha, { zone: TZ }).set({ hour: hh, minute: mm });
return [{ json: { ok: true, crear: true, ...base, hora: req.hora,
  inicio: inicio.toISO(), fin: inicio.plus({ minutes: req.duracion_min }).toISO(),
  titulo: '💈 ' + req.servicio + ' - ' + req.nombre,
  descripcion: 'Cliente: ' + req.nombre + '\nTeléfono: ' + (req.telefono || 'N/D') + '\nServicio: ' + req.servicio + ' ($' + req.precio + ')\nAgendado por Sofi (WhatsApp)',
  nombre: req.nombre, ubicacion: req.direccion } }];

// Respuesta final para el agente tras crear el evento.
const c = $('Calcular turnos').first().json;
const ev = $input.first().json;
if (!ev.id) {
  return [{ json: { ok: false, error: 'NO_SE_CREO_EVENTO', mensaje: 'Google Calendar no confirmó la cita' } }];
}
return [{ json: { ok: true, agendada: true, fecha: c.fecha, dia_semana: c.dia_semana, hora: c.hora,
  servicio: c.servicio, precio: c.precio, cliente: c.nombre, event_id: ev.id, link: ev.htmlLink } }];
